namespace ReelDiscovery.Tests.Evidence.Golden;

// Frozen before the Phase 6 composer change (06-09): Base64 (UTF-8, LF line endings) of the Phase 5 EmailComposer.Compose
// PlainText / Html / HtmlFragment for three EvidenceTestData threads (F-003 reply/forward chain, F-001 Banner,
// F-004 external sender). Emails of a thread are joined with "\n=====\n"; the disclaimer PNG is masked
// (ComposeHtmlGoldenFixtures.MaskBanner). Bodies: "Body of message {seq} about the window schedule.\n\nSecond
// **paragraph** & <stuff>.", sign-off "Thanks,", LengthBand.Medium. Do not regenerate.
internal static class EmailComposerGolden
{
    public const string Separator = "\n=====\n";

    public const string ReplyPlainText = "";
    public const string ReplyHtml = "";
    public const string ReplyHtmlFragment = "";
    public const string BannerPlainText = "";
    public const string BannerHtml = "";
    public const string BannerHtmlFragment = "";
    public const string ExternalPlainText = "";
    public const string ExternalHtml = "";
    public const string ExternalHtmlFragment = "";

    public static string Get(string field)
    {
        var value = (string)typeof(EmailComposerGolden).GetField(field)!.GetValue(null)!;
        return System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(value));
    }
}
